function BranchCard({ branch, index, merges = [], discoveryRole = false }: { branch: Branch; index: number; merges?: MergeRow[]; discoveryRole?: boolean }) {
  return <article className="branch-card"><div className="branch-title"><span>{String(index + 1).padStart(2, "0")}</span><h4>{branch.title}</h4></div><div className="unit-list">{branch.units.map((unit, unitIndex) => typeof unit === "string" ? <div key={unit}><i aria-hidden="true" />{unit}</div> : <div className="unit-options" key={`options-${unitIndex}`}><i aria-hidden="true" /><span><small>خياران للمسمى</small>{unit.options.map((option, optionIndex) => <b key={option}>{optionIndex > 0 && <em>أو</em>}{option}</b>)}</span></div>)}</div>{discoveryRole && <div className="discovery-role"><small>دور مقترح</small><b>مسؤول استكشاف الابتكارات والمواهب</b><p>يتولى الوصول إلى كليات الجامعة، واكتشاف المبتكرين من الطلاب وأعضاء هيئة التدريس، وتوجيههم وربطهم بالخدمة المناسبة داخل المركز.</p></div>}{branch.note && <p className="role-note">{branch.note}</p>}{merges.length > 0 && <CompactMerge rows={merges} />}</article>;
}

function CompactMerge({ rows }: { rows: MergeRow[] }) {
  return <details className="branch-merge"><summary><b>عرض طريقة الدمج</b><span aria-hidden="true">+</span></summary><div className="compact-merges">{rows.map((row, index) => <div className="compact-merge-row" key={`${row.to}-${index}`}><p>{row.from}</p><div><b>{row.action}</b><i aria-hidden="true">←</i></div>{row.toOptions ? <section className="merge-result-options">{row.toOptions.map((option, optionIndex) => <span key={option}>{optionIndex > 0 && <em>أو</em>}<strong>{option}</strong></span>)}</section> : <strong>{row.to}</strong>}</div>)}</div></details>;
}

function OperationalCard({ branch, index }: { branch: OperationalBranch; index: number }) {
  return <article className="operational-card"><div className="operational-head"><span>{String(index + 1).padStart(2, "0")}</span><b>{branch.title}</b></div><div className="coordinator-role">{branch.coordinator}</div><div className="operational-units">{branch.units.map((unit) => <section key={unit.title}>{unit.titleOptions ? <div className="operational-title-options">{unit.titleOptions.map((option, optionIndex) => <h4 key={option}>{optionIndex > 0 && <><em>أو</em>{" "}</>}{option}</h4>)}</div> : <h4>{unit.title}</h4>}<ul>{unit.roles.map((role) => <li key={role}>{role}</li>)}</ul></section>)}</div></article>;
}

function mergeRowsFor(title: string, fourDeputies: boolean): MergeRow[] {
  if (title === "مدير إدارة المركز") return fourDeputies ? administrationMergesFour : administrationMergesThree;
  if (title.includes("للابتكار")) return fourMerges.slice(0, 2);
  if (title.includes("لريادة الأعمال")) return fourMerges.slice(6, 8);
  if (fourDeputies && title.includes("للتتجير")) return fourMerges.slice(2, 4);
  if (fourDeputies && title.includes("للملكية الفكرية")) return fourMerges.slice(4, 6);
  if (!fourDeputies && title.includes("للملكية الفكرية")) return threeMerges.slice(6);
  return [];
}

